// Code generated by tmp-oracle-gen (mpmath, 400-bit); DO NOT EDIT.
//
// Correctly-rounded reference values for the transcendental cross-checks in
// math_trig_test.go, math_pow_test.go and math_explog_test.go. Each map sends the IEEE-754 bit
// pattern of the (double) input to the bit pattern of the correctly-rounded
// double result of the true mathematical function at that exact input.
//
// These replace Go's math package as the oracle: Go's transcendentals are only
// ~1-ULP accurate and are wrong by 7-967 ULP at several of the test inputs,
// whereas the musl port under test is correctly rounded there. Comparing the
// port against Go therefore produced false failures; comparing against these
// mpmath values is both green and rigorous.
//
// Float32 tests reuse these doubles: they promote the float32 input to double,
// look it up, then round the correctly-rounded double result to float32. That
// final double->float32 step is a (harmless) double rounding, well inside the
// 4-ULP-float32 bound the float tests use.
//
// Only finite, in-domain transcendental inputs are present. Inf/NaN/domain and
// other exactly-specified boundary results (e.g. pow(x,0), atan2(y,0)) are
// deliberately absent so oracleRef/oracleRef2 fall back to Go's math, which is
// exact for those — keeping every existing edge-case assertion unchanged.

import "math"

// oracleRef returns a reference function that yields the correctly-rounded
// oracle value for inputs present in m, and falls back to Go's math (exact for
// the omitted special/edge inputs) otherwise.
func oracleRef(m map[uint64]uint64, fallback func(float64) float64) func(float64) float64 {
	return func(x float64) float64 {
		if b, ok := m[math.Float64bits(x)]; ok {
			return math.Float64frombits(b)
		}
		return fallback(x)
	}
}

func oracleRef2(m map[[2]uint64]uint64, fallback func(float64, float64) float64) func(float64, float64) float64 {
	return func(x, y float64) float64 {
		if b, ok := m[[2]uint64{math.Float64bits(x), math.Float64bits(y)}]; ok {
			return math.Float64frombits(b)
		}
		return fallback(x, y)
	}
}

